{
  "objective": "Using validation-only evidence, produce bounded research and risk directives for the frozen Phase 12 protocol. Never access test metrics.",
  "mode": "dry_run",
  "rationale": "The dataset manifest is valid and contains 4 markets (CN, HK, JP, US) with 80 symbols and 73,193 rows. A sequential research plan is designed to first inspect and validate the data, enumerate markets and symbols, create a validation-only split, validate experiment configuration, estimate compute requirements, then proceed to training, tuning, evaluation, comparison, and final reporting. All steps are validation-locked; test metrics will not be accessed. This plan provides a bounded, risk-aware pathway to generate directives without executing heavy computation.",
  "validation_only": true,
  "test_metrics_accessed": false,
  "confidence": 0.9,
  "estimated_compute_units": 12.5,
  "safe_to_execute": false,
  "steps": [
    {
      "id": "step_1",
      "action": "inspect_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": [],
      "expected_artifacts": ["dataset_summary"]
    },
    {
      "id": "step_2",
      "action": "validate_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step_1"],
      "expected_artifacts": ["validation_report"]
    },
    {
      "id": "step_3",
      "action": "list_markets",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step_2"],
      "expected_artifacts": ["market_list"]
    },
    {
      "id": "step_4",
      "action": "list_symbols",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step_3"],
      "expected_artifacts": ["symbol_list"]
    },
    {
      "id": "step_5",
      "action": "create_split",
      "arguments": {
        "method": "time_series",
        "validation_ratio": 0.2,
        "test_ratio": 0.0,
        "seed": 42
      },
      "depends_on": ["step_4"],
      "expected_artifacts": ["split_indices"]
    },
    {
      "id": "step_6",
      "action": "validate_experiment_config",
      "arguments": {
        "protocol": "phase_12",
        "config_path": "configs/phase_12.yaml"
      },
      "depends_on": ["step_5"],
      "expected_artifacts": ["config_validation"]
    },
    {
      "id": "step_7",
      "action": "estimate_compute_budget",
      "arguments": {
        "config_path": "configs/phase_12.yaml",
        "dataset_manifest": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step_6"],
      "expected_artifacts": ["compute_estimate"]
    },
    {
      "id": "step_8",
      "action": "train_rl",
      "arguments": {
        "config_path": "configs/phase_12.yaml",
        "split_indices": "split_indices",
        "validation_only": true
      },
      "depends_on": ["step_7"],
      "expected_artifacts": ["checkpoint"]
    },
    {
      "id": "step_9",
      "action": "tune_rl",
      "arguments": {
        "base_config": "configs/phase_12.yaml",
        "hyperparameter_space": "configs/hparam_space.json",
        "validation_only": true
      },
      "depends_on": ["step_8"],
      "expected_artifacts": ["tuned_checkpoint"]
    },
    {
      "id": "step_10",
      "action": "evaluate_checkpoint",
      "arguments": {
        "checkpoint_path": "tuned_checkpoint",
        "split": "validation",
        "metrics": ["sharpe", "max_drawdown", "win_rate"]
      },
      "depends_on": ["step_9"],
      "expected_artifacts": ["evaluation_metrics"]
    },
    {
      "id": "step_11",
      "action": "compare_runs",
      "arguments": {
        "run_ids": ["baseline", "tuned"],
        "metric": "sharpe"
      },
      "depends_on": ["step_10"],
      "expected_artifacts": ["comparison_report"]
    },
    {
      "id": "step_12",
      "action": "generate_report",
      "arguments": {
        "input_artifacts": ["evaluation_metrics", "comparison_report"],
        "risk_analysis": true,
        "bounded_directives": true
      },
      "depends_on": ["step_11"],
      "expected_artifacts": ["final_report"]
    }
  ]
}
